// TypeScript types from docs/experience_api.schema.json: the UI is typed end to end from the API (GOAL 18.7).
// `--check` fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const schema = JSON.parse(readFileSync(resolve(here, "../../docs/experience_api.schema.json"), "utf8"));
const out = resolve(here, "../src/api/types.gen.ts");

function ty(s) {
  if (s.$ref) return s.$ref.split("/").pop();
  if (s.anyOf) return s.anyOf.map(ty).join(" | ");
  if ("const" in s) return JSON.stringify(s.const);
  if (s.enum) return s.enum.map((v) => JSON.stringify(v)).join(" | ");
  if (s.prefixItems) return `[${s.prefixItems.map(ty).join(", ")}]`;
  switch (s.type) {
    case "string": return "string";
    case "integer":
    case "number": return "number";
    case "boolean": return "boolean";
    case "null": return "null";
    case "array": {
      const inner = s.items ? ty(s.items) : "unknown";
      return inner.includes("|") ? `(${inner})[]` : `${inner}[]`;
    }
    case "object":
      return s.additionalProperties && s.additionalProperties !== true
        ? `{ [key: string]: ${ty(s.additionalProperties)} }` : "{ [key: string]: unknown }";
    default: return "unknown";
  }
}

const models = new Map();
for (const [name, s] of Object.entries(schema)) {
  models.set(name, s);
  for (const [d, def] of Object.entries(s.$defs ?? {})) models.set(d, def);
}

let text = "// Generated by scripts/gen-types.mjs from docs/experience_api.schema.json. Do not edit.\n";
for (const name of [...models.keys()].sort()) {
  const s = models.get(name);
  text += `\nexport interface ${name} {\n`;
  const required = new Set(s.required ?? []);
  for (const k of Object.keys(s.properties ?? {}).sort()) {
    text += `  ${k}${required.has(k) ? "" : "?"}: ${ty(s.properties[k])};\n`;
  }
  text += "}\n";
}

if (process.argv.includes("--check")) {
  if (readFileSync(out, "utf8").replaceAll("\r\n", "\n") !== text) {
    console.error("src/api/types.gen.ts is out of date: run `npm run gen`.");
    process.exit(1);
  }
} else {
  writeFileSync(out, text);
}
